-- ============================================
-- LUMA — Enrichissement Thématique 5 (Urgence médicale) : scénarios longs
-- ============================================

update scenarios set content = '{"characters": {"doctor": "le médecin", "admin": "l''administration"}, "start_node": "n1", "nodes": {"n1": {"speaker": "doctor", "text": "We''d like to keep you overnight for observation.", "text_fr": "On aimerait vous garder cette nuit en observation.", "choices": [{"text": "Okay, is my travel insurance accepted here?", "next": "n2"}, {"text": "Is that really necessary? I have a flight tomorrow.", "next": "n2b"}]}, "n2": {"speaker": "admin", "text": "Let me check your policy — yes, it''s covered.", "text_fr": "Laissez-moi vérifier votre police — oui, c''est couvert.", "choices": [{"text": "That''s a relief, thank you.", "next": "n3"}]}, "n2b": {"speaker": "doctor", "text": "I understand the concern, but your symptoms need monitoring. Your safety comes first.", "text_fr": "Je comprends l''inquiétude, mais vos symptômes doivent être surveillés. Votre sécurité passe avant tout.", "choices": [{"text": "You''re right, I''ll change my flight then.", "next": "n3b"}]}, "n3": {"speaker": "doctor", "text": "You''ll need to rest, but you should be discharged by tomorrow morning.", "text_fr": "Vous devrez vous reposer, mais vous devriez sortir demain matin.", "choices": [{"text": "Understood, thank you for taking care of me.", "next": "n4"}]}, "n3b": {"speaker": "admin", "text": "I can help you contact the airline about rebooking, don''t worry.", "text_fr": "Je peux vous aider à contacter la compagnie pour changer de vol, ne vous inquiétez pas.", "choices": [{"text": "Thank you, that''s one less thing to worry about.", "next": "n4"}]}, "n4": {"speaker": "doctor", "text": "(next morning) Your vitals look great. Any lingering symptoms?", "text_fr": "(le lendemain matin) Vos constantes sont bonnes. Des symptômes persistants ?", "choices": [{"text": "No, I feel much better, thank you.", "next": "end_discharged"}, {"text": "Just a bit tired, but otherwise fine.", "next": "end_tired"}]}, "end_discharged": {"speaker": "doctor", "text": "Great, you''re cleared to go. Take care, and safe travels home.", "text_fr": "Parfait, vous pouvez sortir. Prenez soin de vous, et bon retour.", "end": true, "ending_label": "Séjour bien géré, sortie rapide 🏥"}, "end_tired": {"speaker": "doctor", "text": "That''s normal, just take it easy for a couple of days.", "text_fr": "C''est normal, allez-y doucement pendant quelques jours.", "end": true, "ending_label": "Séjour bien géré, repos conseillé 😌"}}}'::jsonb, is_playable = true
where title = 'Un séjour bref à l''hôpital à l''étranger'
  and theme_id = (select id from scenario_themes where position = 5 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"stranger": "un passant", "operator": "l''opérateur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "stranger", "text": "(speaking a language you don''t understand, pointing at an injured person)", "text_fr": "(parle une langue que vous ne comprenez pas, en montrant une personne blessée)", "choices": [{"text": "I''ll call emergency services right now.", "next": "n2"}, {"text": "Try using a translation app to communicate.", "next": "n2b"}, {"text": "Look for anyone nearby who might translate.", "next": "n2c"}]}, "n2": {"speaker": "operator", "text": "Emergency services, what''s happening?", "text_fr": "Services d''urgence, que se passe-t-il ?", "choices": [{"text": "Someone is injured, I don''t know the exact cause, but they need help urgently.", "next": "n3"}]}, "n2b": {"speaker": "stranger", "text": "(the app translates: \"He fell off his bike, his arm looks broken.\")", "text_fr": "(l''appli traduit : \"Il est tombé de vélo, son bras semble cassé.\")", "choices": [{"text": "Thank you, now I can explain clearly to the operator.", "next": "n2"}]}, "n2c": {"speaker": "stranger", "text": "(a nearby tourist overhears and offers to help translate)", "text_fr": "(un touriste à proximité entend et propose d''aider à traduire)", "choices": [{"text": "Thank you so much, could you help me explain to emergency services?", "next": "n2"}]}, "n3": {"speaker": "operator", "text": "Help is on the way, stay with the person. Can you tell if they''re conscious?", "text_fr": "Les secours arrivent, restez avec la personne. Elle est consciente ?", "choices": [{"text": "Yes, he''s conscious and talking, just in a lot of pain.", "next": "n4"}, {"text": "He seems dazed, not fully responsive.", "next": "n4b"}]}, "n4": {"speaker": "operator", "text": "Good, keep him calm and still until help arrives.", "text_fr": "Bien, gardez-le calme et immobile jusqu''à l''arrivée des secours.", "choices": [{"text": "Understood, I''ll stay right here with him.", "next": "end_help"}]}, "n4b": {"speaker": "operator", "text": "Keep monitoring him closely, and let me know if anything changes.", "text_fr": "Continuez à le surveiller de près, et prévenez-moi si quelque chose change.", "choices": [{"text": "Will do, I won''t leave his side.", "next": "end_help"}]}, "end_help": {"speaker": "operator", "text": "The ambulance is two minutes away. Well done staying calm.", "text_fr": "L''ambulance arrive dans deux minutes. Bravo d''être resté calme.", "end": true, "ending_label": "Communication réussie malgré la barrière 🌍"}}}'::jsonb, is_playable = true
where title = 'Gérer une urgence avec la barrière de la langue'
  and theme_id = (select id from scenario_themes where position = 5 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"doctor": "le médecin"}, "start_node": "n1", "nodes": {"n1": {"speaker": "doctor", "text": "How have you been feeling since our last appointment?", "text_fr": "Comment vous êtes-vous senti depuis notre dernier rendez-vous ?", "choices": [{"text": "Much better, the medication is working well.", "next": "n2"}, {"text": "Honestly, not much has changed.", "next": "n2b"}, {"text": "Actually, I''ve had some new symptoms appear.", "next": "n2c"}]}, "n2": {"speaker": "doctor", "text": "That''s great news, let''s continue the current treatment.", "text_fr": "Excellente nouvelle, continuons le traitement actuel.", "choices": [{"text": "Sounds good, thank you.", "next": "n3"}]}, "n2b": {"speaker": "doctor", "text": "Let''s adjust the dosage and see how that goes.", "text_fr": "Ajustons la dose et voyons comment ça évolue.", "choices": [{"text": "Okay, I''ll follow the new plan.", "next": "n3b"}]}, "n2c": {"speaker": "doctor", "text": "Tell me more about these new symptoms, when did they start?", "text_fr": "Parlez-moi de ces nouveaux symptômes, quand ont-ils commencé ?", "choices": [{"text": "About three days ago, mild dizziness in the mornings.", "next": "n3c"}]}, "n3": {"speaker": "doctor", "text": "See you in two weeks for a follow-up.", "text_fr": "On se revoit dans deux semaines pour un suivi.", "choices": [{"text": "I''ll be there, thank you doctor.", "next": "end_continue"}]}, "n3b": {"speaker": "doctor", "text": "We''ll monitor closely and adjust as needed.", "text_fr": "On surveillera de près et ajustera si besoin.", "choices": [{"text": "Thank you for staying flexible with the treatment.", "next": "end_adjust"}]}, "n3c": {"speaker": "doctor", "text": "That could be a minor side effect. Let''s run a quick check to be safe.", "text_fr": "Ça pourrait être un effet secondaire mineur. Faisons une vérification rapide par sécurité.", "choices": [{"text": "Good idea, better safe than sorry.", "next": "n4"}]}, "n4": {"speaker": "doctor", "text": "Everything looks fine, just a minor adjustment needed to the dosage.", "text_fr": "Tout va bien, juste un léger ajustement de dose nécessaire.", "choices": [{"text": "That''s reassuring, thank you for checking thoroughly.", "next": "end_reassured"}]}, "end_continue": {"speaker": "doctor", "text": "Great progress, keep it up!", "text_fr": "Beaux progrès, continuez comme ça !", "end": true, "ending_label": "Traitement efficace ✅"}, "end_adjust": {"speaker": "doctor", "text": "We''ll get this right together, don''t worry.", "text_fr": "On va bien régler ça ensemble, ne vous inquiétez pas.", "end": true, "ending_label": "Traitement ajusté avec soin 🩺"}, "end_reassured": {"speaker": "doctor", "text": "Your health is in good hands, see you at the next check-up.", "text_fr": "Votre santé est entre de bonnes mains, à la prochaine visite.", "end": true, "ending_label": "Suivi rassurant et minutieux 💙"}}}'::jsonb, is_playable = true
where title = 'Un suivi médical sur plusieurs jours'
  and theme_id = (select id from scenario_themes where position = 5 and language_id = (select id from languages where code = 'en'));
